{
  "name": "rf_apply_channel",
  "confidence": "medium",
  "docstring": "Applies a radio channel index by configuring band/channel registers, resetting the associated TX DMA queue when required, and waiting for the hardware channel-switch command to complete.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "channel_idx",
    "v2": "tx_dma_base",
    "v8": "channel_entry",
    "v9": "dma_context_idx",
    "v5": "chan_cmd_reg"
  },
  "struct_hints": [
    {
      "offset": 34,
      "meaning": "associated DMA/TX context index used by the channel entry"
    },
    {
      "offset": 38,
      "meaning": "low 16 bits of channel configuration value written to the first channel register"
    },
    {
      "offset": 40,
      "meaning": "high 16 bits of channel configuration value written to the first channel register"
    },
    {
      "offset": 42,
      "meaning": "16-bit channel configuration value written to the second channel register"
    },
    {
      "offset": 106,
      "meaning": "TX/DMA context state byte; value 2 indicates the context is already configured"
    }
  ]
}
